import{_ as e,o as a,c as s,ag as r}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Part 21 — Observability","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_21_Observability.md","filePath":"todo/study_plan/parts/Part_21_Observability.md"}'),i={name:"todo/study_plan/parts/Part_21_Observability.md"};function n(o,t,d,l,c,h){return a(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="part-21-—-observability" tabindex="-1">Part 21 — Observability <a class="header-anchor" href="#part-21-—-observability" aria-label="Permalink to &quot;Part 21 — Observability&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Light touch — fold into spare slots; you already do this daily. <strong>Budget: ~1-2 hrs (overflow slot).</strong></p></blockquote><h2 id="_21-observability-—-topic-inventory" tabindex="-1">21 Observability — topic inventory <a class="header-anchor" href="#_21-observability-—-topic-inventory" aria-label="Permalink to &quot;21 Observability — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Logs — structured (JSON), levels, correlation IDs</td><td>🔴 💼 🎯</td><td>MP</td><td>1 hr 45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: configure Logback / Logstash encoder for JSON output with correlationId via MDC, hit endpoint, inspect log shape (15 min)</td></tr><tr><td>2</td><td>Metrics — counters, gauges, histograms, summaries; RED &amp; USE methods</td><td>🔴 💼 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Traces — spans, context propagation, OpenTelemetry</td><td>🔴 💼 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Prometheus + Grafana</td><td>🔴 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>Datadog (you use it daily) — APM, logs, metrics, monitors</td><td>🔴 💼</td><td>MP</td><td>1 hr 50 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: define a Datadog custom metric via dd-trace-java + verify in Datadog UI (20 min)</td></tr><tr><td>6</td><td>Alerts — symptom-based not cause-based; runbooks per alert</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>On-call hygiene, incident response</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Events — discrete vs metric aggregation</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>SLO, SLI, SLA — definitions and error budgets</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>ELK / OpenSearch / Loki stacks</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Jaeger, Tempo, AWS X-Ray</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>OpenTelemetry — collector, SDKs, instrumentation</td><td>🟠 💼</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: wire OpenTelemetry Java agent into a Spring Boot app + export to OTLP collector (30 min)</td></tr><tr><td>13</td><td>Postmortems, blameless culture, 5 whys</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Chaos engineering basics</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>Sentry for error tracking</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Synthetic monitoring</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~15.08 hrs</td><td>~1.4 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~24.33 hrs</td><td>~2.2 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~25.83 hrs</td><td>~2.35 wk</td><td></td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>Three pillars and their overlap:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Obs[&quot;Observability&lt;br/&gt;(answer: why is the system behaving this way?)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M[&quot;Metrics&lt;br/&gt;aggregates, trends, alerts&lt;br/&gt;(low cardinality, cheap)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L[&quot;Logs&lt;br/&gt;discrete events, full text&lt;br/&gt;(high detail, high cost)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T[&quot;Traces&lt;br/&gt;request flow across services&lt;br/&gt;(causal structure)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ML[&quot;Metric + Log:&lt;br/&gt;alert with context&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LT[&quot;Log + Trace:&lt;br/&gt;request-scoped diagnosis&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MT[&quot;Metric + Trace:&lt;br/&gt;RED per endpoint,&lt;br/&gt;P99 with example trace&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ALL[&quot;All three together:&lt;br/&gt;full root-cause path&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Obs --&gt; M</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Obs --&gt; L</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Obs --&gt; T</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M --- ML</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L --- ML</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L --- LT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T --- LT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M --- MT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T --- MT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ML --- ALL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LT --- ALL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MT --- ALL</span></span></code></pre></div><blockquote><p>Each pillar answers a different question. The intersections are where real debugging happens — a metric alert that links to an example trace that links to the offending logs.</p></blockquote><p><strong>Trace waterfall (one request, four services):</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant A as Service A (300ms total)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant B as Service B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as Service C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant D as Service D</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A-&gt;&gt;B: call (50ms)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B--&gt;&gt;A: response</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A-&gt;&gt;C: call (200ms — dominates!)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C--&gt;&gt;A: response</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A-&gt;&gt;D: call (40ms)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D--&gt;&gt;A: response</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over A,D: Span tree exposes where time is spent.&lt;br/&gt;Service C is the latency culprit; A&#39;s own work is ~10ms.</span></span></code></pre></div><blockquote><p>The waterfall reveals what a flat metric can&#39;t: which downstream call is dominating P99. Without traces, you&#39;d be guessing.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Three pillars of observability — what does each give you, and when does each fall short? <ul><li><strong>Why asked:</strong> Senior-canonical. Logs: full text events, debugging &quot;what happened on this specific request&quot;. Falls short for aggregates. Metrics: aggregates with low overhead, &quot;what&#39;s the rate of failures over time&quot;. Falls short for individual diagnosis. Traces: end-to-end request flow across services, &quot;where did time go&quot;. Falls short on cost at high cardinality.</li></ul></li><li><strong>Q:</strong> RED vs USE methods — what does each focus on? <ul><li><strong>Why asked:</strong> Modern monitoring standard. RED (for services): Request rate, Errors, Duration. USE (for resources): Utilization, Saturation, Errors. RED for &quot;is my service serving traffic well&quot;, USE for &quot;is my host healthy&quot;. Use both — overlapping but different angles.</li></ul></li><li><strong>Q:</strong> Design alerts for your KYC platform&#39;s verification endpoint. <ul><li><strong>Why asked:</strong> Operational thinking. Symptom-based: (1) Error rate &gt; 1% over 5 min, (2) P99 latency &gt; 2s over 5 min, (3) Throughput drops &gt; 50% from baseline. Avoid cause-based alerts (&quot;CPU &gt; 80%&quot; — symptom of what?). Each alert has a runbook with clear next-action.</li></ul></li><li><strong>Q:</strong> SLO + error budget — pick numbers for KYC verification and justify. <ul><li><strong>Why asked:</strong> SRE-canonical. Example: 99.5% success SLO over 30 days = 3.6 hours / month allowed failure. Tie to customer experience — partner bank tolerates X failures per million. Budget consumption: if you burn 50% in week 1, freeze risky changes until next month.</li></ul></li><li><strong>Q:</strong> OpenTelemetry — what problem does it solve over vendor SDKs (Datadog, X-Ray)? <ul><li><strong>Why asked:</strong> Modern vendor-neutrality. OTel: vendor-neutral instrumentation. Same code outputs to Datadog OR Jaeger OR X-Ray OR Tempo via collector + exporter swap. Avoid vendor lock-in on instrumentation. Caveat: vendor SDKs may have richer features (e.g., DD&#39;s continuous profiling).</li></ul></li><li><strong>Q:</strong> Correlation IDs — how do you propagate across async boundaries? <ul><li><strong>Why asked:</strong> Practical observability. Context propagation: MDC for sync code, ContextSnapshot or Scoped Values for virtual threads, propagation header (W3C <code>traceparent</code>) across HTTP/gRPC, message header in Kafka. The hardest case: <code>CompletableFuture.supplyAsync</code> to a default ForkJoinPool — manually wrap with MDC.transfer or use Micrometer&#39;s ContextSnapshot.</li></ul></li><li><strong>Q:</strong> Your P99 alert fires nightly at 3am. What&#39;s the canonical fix? <ul><li><strong>Why asked:</strong> Operational maturity. Likely a batch job. Options: (1) silence the alert window, (2) split SLO into &quot;interactive&quot; vs &quot;batch&quot;, (3) move the batch off the user-facing service, (4) accept periodic slow path. The right answer depends on whether the batch is intentional or a regression.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your CloudWatch alarm fired but Datadog didn&#39;t. Both monitor the same metric. Why? <ul><li><strong>Gotcha:</strong> Different aggregation windows or data sources. CloudWatch may see EC2-level metrics; Datadog may see app-level. Also: aggregation method (max vs avg over window). Always check the actual data series used by each alert.</li></ul></li><li><strong>Q:</strong> You added <code>correlationId</code> to every log line. But traces don&#39;t tie together across services. Why? <ul><li><strong>Gotcha:</strong> You didn&#39;t propagate the correlationId to downstream calls. Need to: (1) set in MDC at request entry, (2) include in outgoing headers (e.g., <code>X-Correlation-ID</code> or W3C <code>traceparent</code>), (3) downstream service extracts on entry, sets in its MDC. Spring Cloud Sleuth / Micrometer Tracing handles this automatically.</li></ul></li><li><strong>Q:</strong> Your synthetic monitor probes your KYC endpoint every minute. You don&#39;t have real traffic at 3am. The probe goes from 100ms to 5s. Did your service degrade? <ul><li><strong>Gotcha:</strong> Maybe — or the probe itself moved (e.g., AWS Synthetics rotating regions, DNS change). Synthetic checks need careful baselining: track the probe path, not just response time. Cross-reference with real-traffic metrics during the same window.</li></ul></li><li><strong>Q:</strong> Your service emits 10,000 logs/sec. Your bill jumps. What&#39;s the optimization? <ul><li><strong>Gotcha:</strong> Common cost trap. (1) Drop DEBUG logs in prod. (2) Sample log lines if appropriate (1 in N for high-volume info logs). (3) Use metrics for things that don&#39;t need full text (request count). (4) Aggregate first, log second (avoid per-request audit logs if a counter would suffice).</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Correlation ID + context propagation end-to-end</strong> (~3 hrs row 1 + 12) — across MDC, threads, async, downstream HTTP. Directly job-relevant (you use Datadog daily).</li><li><strong>Alerts + runbook design</strong> (~2.5 hrs rows 6+7) — symptom-based alerts, runbook structure (steps, escalation, mitigations). Build a runbook for KYC verification failures.</li><li><strong>SLO + error budget for KYC platform</strong> (~2 hrs row 9) — pick numbers, justify, document budget-consumption logic. SRE-style.</li><li><strong>OpenTelemetry instrumentation</strong> (~3 hrs row 12) — vendor-neutral instrumentation. Wire OTel agent into a Spring Boot service. Export to Datadog AND Jaeger via OTLP collector.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up observability exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Structured JSON logging with correlationId</strong> (~45 min) — Spring Boot + Logstash encoder. HandlerInterceptor generates correlationId at request entry, puts into MDC, clears at exit. Output JSON logs with embedded correlationId, traceId, spanId. Hit endpoint, search by correlationId in stdout.</li><li><strong>Custom Datadog metric via Micrometer</strong> (~45 min) — Spring Boot + Micrometer + dd-trace-java. Define a Counter for verification_attempts + a Timer for verification_duration. Verify metrics appear in Datadog UI. Add a tag for tenant_id.</li><li><strong>OpenTelemetry tracing across two services</strong> (~60 min) — two Spring Boot services. Service A calls Service B. OTel Java agent instruments both. Export to local Jaeger via OTLP collector. Verify trace spans connect across the call.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Alert + runbook design</strong> (~75 min) — pick 3 metrics that matter for KYC verification (success rate, P99 latency, throughput). Define symptom-based alerts (not cause-based). Write a runbook for each: triage steps, mitigations, escalation. Document expected MTTA + MTTR.</li><li><strong>SLO + error budget calculation</strong> (~60 min) — pick a 30-day window. Compute current SLO baseline. Define error budget. Walk through &quot;if we burn 50% of budget in week 1, what does that mean for risky deploys?&quot;. Document the policy.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.25 hrs</td><td>~0.2 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~4.75 hrs</strong></td><td><strong>~0.43 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~65 min for Part 21 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Three pillars of observability?</strong> A. Logs (text events, debugging), Metrics (low-cost aggregates, trends), Traces (request flow across services). Each excels at different questions; use all three.</p><p><strong>Q. RED method for services?</strong> A. Rate (requests/sec), Errors (count or %), Duration (latency p50/p99). The three numbers that tell you if a service is serving traffic well.</p><p><strong>Q. USE method for resources?</strong> A. Utilization (% in use), Saturation (queue depth, wait), Errors (HW or driver errors). For host-level health monitoring.</p><p><strong>Q. Symptom-based vs cause-based alerts.</strong> A. Symptom: user-visible (error rate, latency). Cause: internal (CPU, memory). Alert on symptoms (those page humans); use cause metrics for diagnosis. Cause-based alerts cause alert fatigue.</p><p><strong>Q. SLO vs SLA vs SLI?</strong> A. SLI: indicator (the actual metric you measure, e.g., success rate). SLO: objective (target you set, e.g., 99.5%). SLA: agreement (contractual promise to customer; usually weaker than internal SLO).</p><p><strong>Q. Correlation ID propagation — minimum stack?</strong> A. (1) Set in MDC at request entry (HandlerInterceptor). (2) Include in outgoing headers (Feign interceptor or RestTemplate ClientHttpRequestInterceptor). (3) Receiving service reads header and sets in its MDC. (4) Clear MDC at request exit.</p>`,35)])])}const u=e(i,[["render",n]]);export{g as __pageData,u as default};
